package org.telegram.messenger.purple;
import android.content.Intent;
import androidx.core.content.pm.*;
import org.telegram.messenger.*;
import org.telegram.tgnet.TLRPC;
public final class PurpleDirectShareRoutingCases {
 static void check(boolean v,String why){if(!v)throw new AssertionError(why);}
 static void drain(){int n=0;while(!AndroidUtilities.pending.isEmpty()||!Utilities.globalQueue.pending.isEmpty()){check(++n<12,"bounded scheduler");AndroidUtilities.drain();Utilities.globalQueue.drain();}}
 static void hint(int slot,long peer){TLRPC.TL_topPeer h=new TLRPC.TL_topPeer();h.peer=new TLRPC.TL_peerUser();h.peer.user_id=peer;MediaDataController.getInstance(slot).hints.add(h);TLRPC.TL_user u=new TLRPC.TL_user();u.id=peer;u.first_name="synthetic";u.last_name="";MessagesController.getInstance(slot).users.put(peer,u);}
 public static void main(String[] args){
  if(args[0].startsWith("legacy")){
   int ownerSlot=args[0].equals("legacy-partial")?1:0;UserConfig.getInstance(ownerSlot).active=true;UserConfig.getInstance(ownerSlot).user=22;UserConfig.selectedAccount=ownerSlot;
   if(ownerSlot==1){UserConfig.getInstance(0).active=true;UserConfig.getInstance(0).user=11;}
   TLRPC.TL_dialog d=new TLRPC.TL_dialog();d.id=7;MessagesController.getInstance(ownerSlot).dialogs_dict.put(7,d);
   Intent old=new Intent().setAction("com.tmessages.openchat_legacy").putExtra("userId",7L);if(args[0].equals("legacy"))old.putExtra("currentAccount",0);
   ShortcutManagerCompat.targets.put("ndid_7",new ShortcutInfoCompat.Builder(ApplicationLoader.applicationContext,"ndid_7").setShortLabel("synthetic former A").setIntent(old).build());
   PurpleDirectShare.request();drain();
   check(!ShortcutManagerCompat.targets.containsKey("ndid_7")&&!ShortcutManagerCompat.targets.containsKey("pndid_0-22_7"),"unproved legacy owner is retired, never inherited by B");
   Intent routed=PurpleDirectShare.routeShare(new Intent().setAction(Intent.ACTION_SEND).putExtra(ShortcutManagerCompat.EXTRA_SHORTCUT_ID,"pndid_0-22_7"));check(!routed.hasExtra("currentAccount")&&!routed.hasExtra("dialogId"),"retired legacy target does not admit B");
   System.out.println("LEGACY: unqualified former_A_target retired=true relay_admits_B=false");
  }else if(args[0].equals("launcher")||args[0].equals("handoff")){
   UserConfig.getInstance(0).active=true;UserConfig.getInstance(0).user=11;UserConfig.getInstance(1).active=true;UserConfig.getInstance(1).user=22;UserConfig.selectedAccount=1;hint(0,7);hint(1,8);PurpleDirectShare.request();drain();
   ShortcutInfoCompat a=ShortcutManagerCompat.targets.get("pdid_0-11_7");check(a!=null,"published A shortcut");Intent saved=new Intent(a.getIntent());
   Intent routed=PurpleDirectShare.routeShare(new Intent().setAction(Intent.ACTION_SEND).putExtra(ShortcutManagerCompat.EXTRA_SHORTCUT_ID,a.getId()));check(routed.getIntExtra("currentAccount",-1)==0&&routed.getLongExtra("dialogId",0)==7,"share resolves A before handoff");
   UserConfig.getInstance(0).user=33;++UserConfig.getInstance(0).lifetime;
   Intent refused=PurpleDirectShare.routeShare(new Intent().setAction(Intent.ACTION_SEND).putExtra(ShortcutManagerCompat.EXTRA_SHORTCUT_ID,a.getId()));check(!refused.hasExtra("currentAccount")&&!refused.hasExtra("dialogId"),"fresh relay validation correctly refuses stale A");
   check(!PurpleDirectShare.admitShortcut(ApplicationLoader.applicationContext,saved),"retained launcher pin is refused at receiver");
   check(!PurpleDirectShare.admitIncoming(ApplicationLoader.applicationContext,routed),"relay handoff is refused after slot reuse");
   System.out.println("ROUTING: retained_launcher_refused=true relay_handoff_refused=true fresh_revalidation_refuses=true");
  }else if(args[0].equals("session")){
   UserConfig c=UserConfig.getInstance(0);c.active=true;c.user=11;c.lifetime=0;c.loginSession=1;hint(0,7);PurpleDirectShare.request();drain();
   Intent pin=new Intent(ShortcutManagerCompat.targets.get("pdid_0-11_7").getIntent());
   check(PurpleDirectShare.currentIntent(pin),"same-login persisted target is valid");
   c.lifetime=41;check(PurpleDirectShare.currentIntent(pin),"a process-local lifetime is not a persistent login identity");
   c.loginSession=2;c.lifetime=0;check(!PurpleDirectShare.currentIntent(pin),"a new login after a process reset cannot reuse the old lifetime-zero pin");
   c.missingLogin=true;check(PurpleDirectShare.bindShortcut(0,7,pin)==null,"a missing login anchor is never generated by publication");
   System.out.println("SESSION: same_login_valid=true new_login_after_restart_refused=true missing_anchor_refused=true");
  }else if(args[0].equals("multiple")){
   UserConfig.getInstance(0).active=true;UserConfig.getInstance(0).user=11;hint(0,7);PurpleDirectShare.request();drain();Intent r=PurpleDirectShare.routeShare(new Intent().setAction(Intent.ACTION_SEND_MULTIPLE).putExtra(ShortcutManagerCompat.EXTRA_SHORTCUT_ID,"pdid_0-11_7"));
   check(Intent.ACTION_SEND_MULTIPLE.equals(r.getAction())&&r.getLongExtra("dialogId",0)==7&&r.getIntExtra("currentAccount",-1)==0,"batch relay prepares recipient but retains unsupported receiver branch");check(PurpleDirectShare.admitIncoming(ApplicationLoader.applicationContext,r)&&PurpleDirectShare.shareRecipient(r)==7,"the common receiver consumes the multiple-share recipient");System.out.println("MULTIPLE: common_receiver_recipient=7 final_admission=true");
  }else throw new AssertionError("mode");
 }
}
